" for(const k of ['enabled','invert_x','invert_y','hotkeys_enabled'])$(k).checked=!!s.config[k];$('activation').value=s.config.activation;$('toggle_mode').value=s.config.toggle_mode;\n"
" $('undo').disabled=!s.can_undo;$('beginTest').hidden=!!s.testing;$('keepTest').hidden=$('revertTest').hidden=!s.testing;\n"
" $('testHelp').textContent=s.testing\?'Ponto marcado neste jogo. Experimente e escolha manter ou voltar.':'Marque como está agora, experimente novos valores e escolha se quer manter ou voltar.';\n"
" $('calibrate').disabled=!s.input_ready||!!s.calibration.active;for(const b of $('guideActions').children){if(b.textContent==='Calibrar agora')b.disabled=!s.input_ready||!!s.calibration.active;if(b.textContent==='Marcar ponto de retorno')b.disabled=!!s.testing;}$('cancelCalibration').hidden=!s.calibration.active;$('calibration').textContent=s.calibration.active\?'Calibrando… '+Math.round(s.calibration.progress*100)+'% · não toque no controle':'Compensação salva: pitch '+s.config.bias_pitch.toFixed(2)+' · yaw '+s.config.bias_yaw.toFixed(2)+' °/s';\n"
" const l=s.live;draw(l);$('active').className='dot'+(s.input_ready&&l.active\?' on':'');$('activeText').textContent=!s.input_ready\?'Sensor desconectado':s.paused\?'Gyro pausado':s.calibration.active\?'Calibrando sensor':s.remote_play&&s.title==='default'\?'Gyro suspenso · selecione um jogo':l.active\?'Gyro ativo':'Gyro inativo';$('rates').textContent=`Pitch ${l.pitch.toFixed(1)} · yaw ${l.yaw.toFixed(1)} °/s`;\n"
" if(lastSeq>=0&&s.message_seq!==lastSeq)toast(s.message);lastSeq=s.message_seq;\n"
" if(s.save_error)$('saving').textContent='Falha de gravação; ajuste anterior mantido.';else if(!mutating)$('saving').textContent=s.testing\?'Teste em andamento · alterações salvas':s.has_profile\?'Perfil carregado · alterações salvas ao ajustar':'Pronto para ajustar';\n"
" lock();\n"
"}\n"
"async function refresh(force=false){const r=await timedFetch('/api/state',{},2500);if(!r.ok)throw Error('state');const result=await r.json();if(!mutating||force)render(result)}\n"
"async function poll(){if(!mutating&&!polling){polling=true;try{await refresh()}catch(e){disconnected()}finally{polling=false}}setTimeout(poll,250)}\n"
"renderGuide();poll();\n"
"</script></body></html>\n";

