"<!doctype html>\n"
"<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Gyro Aim · Treino Linux</title>\n"
"<style>\n"
":root{color-scheme:dark;font:14px/1.45 system-ui,sans-serif;color:#eaf1ff;background:#0b1019}*{box-sizing:border-box}body{margin:0}button,select,input{font:inherit}button,select{background:#172235;color:#eaf1ff;border:1px solid #3b4b65;border-radius:9px;padding:10px 12px;min-height:42px}button{cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid #85bdff;outline-offset:3px}header{padding:13px 18px;border-bottom:1px solid #29374b;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:20px;margin:0}.muted{color:#a9b9d0}.eyebrow{font-size:10px;color:#8fbeff;letter-spacing:1.7px;text-transform:uppercase}a{color:#8fbeff}.layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;height:calc(100dvh - 80px);min-height:600px}.layout.without-panel{grid-template-columns:1fr}.arena{min-width:0;position:relative;display:flex;flex-direction:column}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:12px 18px;background:#111a29;border-bottom:1px solid #29374b}.toolbar label{display:flex;align-items:center;gap:8px}.toolbar input{width:100px;accent-color:#85bdff}.view{position:relative;flex:1;min-height:350px;overflow:hidden}canvas{display:block;width:100%;height:100%;background:#0e1724}.hud{position:absolute;left:18px;top:15px;right:18px;display:flex;gap:8px;flex-wrap:wrap;pointer-events:none}.pill{padding:5px 10px;border:1px solid #3b4e69;border-radius:7px;background:#101b2ade;font-size:12px;font-variant-numeric:tabular-nums}.good{color:#84e8bb}.warning{color:#ffd58b}.message{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);background:#111d30ed;border:1px solid #4f6e97;border-radius:14px;padding:18px;max-width:90%;width:440px;text-align:center;pointer-events:none}.message[hidden]{display:none}.instructions{padding:13px 18px;background:#101925;border-top:1px solid #29374b}.instructions p{margin:4px 0}kbd{font:12px system-ui;color:#eaf1ff;border:1px solid #445570;border-radius:4px;padding:1px 5px}.panel{border-left:1px solid #3a4b65;display:flex;flex-direction:column;min-height:0}.panel-head{padding:9px 14px;background:#17243a;font-size:12px;color:#b8cae5;display:flex;justify-content:space-between}iframe{width:100%;height:100%;min-height:0;flex:1;border:0}.panel[hidden]{display:none}.footer{font-size:12px;color:#a9b9d0}@media(max-width:850px){.layout{display:flex;flex-direction:column;height:auto;min-height:0}.view{height:55dvh;min-height:360px;flex:none}.panel{height:650px;border-left:0;border-top:1px solid #3a4b65}.toolbar select{max-width:100%}}\n"
"</style></head><body>\n"
"<header><div><div class=\"eyebrow\">Laboratório local · sem PS5</div><h1>Treino de mira</h1><div class=\"muted\">Jogue e ajuste o perfil na mesma tela.</div></div><div><button id=\"recenter\">Centralizar câmera</button> <button id=\"togglePanel\">Ocultar ajustes</button> <a href=\"/\" target=\"_blank\" rel=\"noopener\">Painel completo ↗</a></div></header>\n"
"<main class=\"layout\" id=\"layout\"><section class=\"arena\" aria-label=\"Área de treino\"><div class=\"toolbar\"><label for=\"source\">Entrada <select id=\"source\"><option value=\"gamepad\">Controle virtual real</option><option value=\"keyboard\">Teclado (demonstração)</option></select></label><select id=\"pads\" aria-label=\"Controle do treino\"><option value=\"\">Aguardando controle virtual…</option></select><label for=\"deadzone\">Zona morta do treino <input type=\"range\" id=\"deadzone\" min=\"0\" max=\"30\" value=\"15\" step=\"1\"><output id=\"deadzoneValue\">15%</output></label></div>\n"
"<div class=\"view\"><canvas id=\"scene\" tabindex=\"0\" aria-label=\"Treino: mire nos círculos e aperte X ou R2 para atirar\"></canvas><div class=\"hud\"><span class=\"pill\" id=\"status\" role=\"status\">Pressione X no controle para ele aparecer no navegador.</span><span class=\"pill\" id=\"profile\">Perfil: conectando…</span><span class=\"pill\" id=\"axes\">Analógico: 0,00 · 0,00</span><span class=\"pill\" id=\"score\">Acertos 0 / 0</span></div><div class=\"message\" id=\"message\"><b>Prepare o DualSense</b><p>Pressione X no controle. Depois segure L2 e gire para mover a câmera.</p><small>O treino lê o controle virtual do Linux. Não usa a saída calculada do painel como substituta.</small></div></div>\n"
"<div class=\"instructions\"><p id=\"help\"><kbd>L2 + movimento</kbd> mirar · <kbd>analógico direito</kbd> câmera · <kbd>X / R2</kbd> atirar</p><p class=\"muted\">Ajuste a sensibilidade e a compensação no painel. A zona morta acima simula a opção interna de um jogo e vale só neste treino.</p><div class=\"footer\" id=\"backend\">Verificando aplicativo…</div></div></section>\n"
"<aside class=\"panel\" id=\"panel\"><div class=\"panel-head\"><span>Ajustes durante o treino</span><a href=\"/compact\" target=\"_blank\" rel=\"noopener\">Abrir à parte ↗</a></div><iframe src=\"/compact\" title=\"Ajustes do Gyro Aim\" allow=\"gamepad\"></iframe></aside></main>\n"
"<script>\n"
"'use strict';\n"
"const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');\n"
"let yaw=0,pitch=0,hits=0,shots=0,flash=0,previousFire=false,last=0,available='',selected=null,app=null,keys=new Set();\n"
"let targets=[{x:0,y:0},{x:17,y:-9},{x:-22,y:7},{x:34,y:15},{x:-39,y:-14},{x:8,y:22}];\n"
"const wrap=v=>((v+180)%360+360)%360-180;\n"
"const clearInput=()=>{keys.clear();previousFire=false;last=0};\n"
"window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',clearInput);\n"
"window.addEventListener('keydown',e=>{if($('source').value!=='keyboard'||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)){e.preventDefault();keys.add(e.code)}});\n"
"window.addEventListener('keyup',e=>keys.delete(e.code));\n"
"$('source').onchange=()=>{clearInput();$('pads').disabled=$('source').value==='keyboard';$('help').textContent=$('source').value==='keyboard'\?'Setas: câmera · Espaço: atirar · demonstração sem testar o gyro':'L2 + movimento: mirar · analógico direito: câmera · X / R2: atirar';canvas.focus()};\n"
"$('pads').onchange=()=>{selected=$('pads').value;clearInput()};\n"
"$('deadzone').oninput=()=>$('deadzoneValue').textContent=$('deadzone').value+'%';\n"
"$('recenter').onclick=()=>{yaw=pitch=0;clearInput();canvas.focus()};\n"
"$('togglePanel').onclick=()=>{$('panel').hidden=!$('panel').hidden;$('layout').classList.toggle('without-panel',$('panel').hidden);$('togglePanel').textContent=$('panel').hidden\?'Mostrar ajustes':'Ocultar ajustes'};\n"
"function gamepad(){let pads;try{pads=Array.from(navigator.getGamepads\?.()||[]).filter(p=>p&&p.connected)}catch(e){pads=[]}\n"
" const signature=pads.map(p=>p.index+':'+p.id).join('|');\n"
" if(signature!==available){available=signature;$('pads').replaceChildren();for(const p of pads){const o=document.createElement('option');o.value=''+p.index;o.textContent=p.id;$('pads').append(o)}\n"
" const exact=pads.find(p=>/gyro aim virtual/i.test(p.id));\n"
" if(!pads.some(p=>''+p.index===selected))selected=exact\?''+exact.index:null;\n"
" if(selected===null&&pads.length){const o=document.createElement('option');o.value='';o.textContent='Selecione o controle virtual';$('pads').prepend(o)}\n"
" if(!pads.length){const o=document.createElement('option');o.value='';o.textContent='Pressione X para detectar o controle';$('pads').append(o);selected=null}\n"
" $('pads').value=selected\?\?'';clearInput()}\n"
" return pads.find(p=>''+p.index===selected)||null;\n"
"}\n"
"function fire(){shots++;let index=-1,best=2.8;targets.forEach((t,i)=>{const d=Math.hypot(wrap(t.x-yaw),t.y-pitch);if(d<best){best=d;index=i}});if(index>=0){hits++;const t=targets[index];t.x=wrap(t.x+43+index*7);t.y=((hits*11+index*3)%51)-25;flash=1}else flash=-1;$('score').textContent=`Acertos ${hits} / ${shots}`}\n"
"function frame(time){const dt=last\?Math.min((time-last)/1000,.05):0;last=time;\n"
" const keyboard=$('source').value==='keyboard',pad=gamepad();let x=0,y=0,fireDown=false,ready=false,virtual=false;\n"
" if(keyboard){x=(keys.has('ArrowRight')\?1:0)-(keys.has('ArrowLeft')\?1:0);y=(keys.has('ArrowDown')\?1:0)-(keys.has('ArrowUp')\?1:0);fireDown=keys.has('Space');ready=document.hasFocus();$('status').textContent='Demonstração no teclado · clique no campo para jogar';$('status').className='pill warning'}\n"
" else if(pad){x=Number.isFinite(pad.axes[2])\?pad.axes[2]:0;y=Number.isFinite(pad.axes[3])\?pad.axes[3]:0;fireDown=!!(pad.buttons[0]\?.pressed||pad.buttons[7]\?.pressed);ready=pad.mapping==='standard'&&pad.axes.length>=4;virtual=/gyro aim virtual/i.test(pad.id);$('status').textContent=!ready\?'Mapeamento não suportado neste treino':virtual\?'Lendo controle virtual real':'Controle selecionado · confirme que é o virtual';$('status').className='pill '+(ready&&virtual\?'good':'warning')}\n"
" else{$('status').textContent=window.isSecureContext\?'Pressione X no controle para ele aparecer no navegador.':'Abra o treino em localhost no PC para usar o controle.';$('status').className='pill warning'}\n"
" if(!document.hasFocus()||document.hidden){x=y=0;fireDown=false}\n"
" $('message').hidden=ready;$('axes').textContent=`Analógico: ${x.toFixed(2)} · ${y.toFixed(2)}`;\n"
" const mag=Math.hypot(x,y),dead=+$('deadzone').value/100;\n"
" if(ready&&mag>dead){const gain=(Math.min(mag,1)-dead)/(1-dead)/mag;yaw=wrap(yaw+x*gain*95*dt);pitch=Math.max(-55,Math.min(55,pitch+y*gain*95*dt))}\n"
" if(ready&&fireDown&&!previousFire)fire();previousFire=fireDown;\n"
" const rect=canvas.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,2),w=Math.round(rect.width*ratio),h=Math.round(rect.height*ratio);\n"
" if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}ctx.setTransform(ratio,0,0,ratio,0,0);const W=rect.width,H=rect.height,scale=W/100;\n"
" const gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,'#111e33');gradient.addColorStop(1,'#09111d');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);\n"
" ctx.lineWidth=1;ctx.strokeStyle='#28405c';ctx.beginPath();for(let v=-180;v<180;v+=10){const xx=W/2+wrap(v-yaw)*scale;if(xx>=0&&xx<=W){ctx.moveTo(xx,0);ctx.lineTo(xx,H)}}for(let v=-70;v<=70;v+=10){const yy=H/2+(v-pitch)*scale;ctx.moveTo(0,yy);ctx.lineTo(W,yy)}ctx.stroke();\n"
" ctx.strokeStyle='#4a6480';ctx.beginPath();ctx.moveTo(0,H/2-pitch*scale);ctx.lineTo(W,H/2-pitch*scale);ctx.stroke();\n"
" targets.forEach((t,i)=>{const px=W/2+wrap(t.x-yaw)*scale,py=H/2+(t.y-pitch)*scale,r=Math.max(9,2.6*scale);if(px<-r||px>W+r||py<-r||py>H+r)return;const aligned=Math.hypot(wrap(t.x-yaw),t.y-pitch)<2.8;ctx.fillStyle=aligned\?'#83e6b9':'#7ab8ff';ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#142239';ctx.beginPath();ctx.arc(px,py,r*.62,0,Math.PI*2);ctx.fill();ctx.fillStyle=aligned\?'#83e6b9':'#7ab8ff';ctx.beginPath();ctx.arc(px,py,r*.2,0,Math.PI*2);ctx.fill()});\n"
" ctx.strokeStyle=flash>0\?'#83e6b9':flash<0\?'#ff9c8d':'#ffffff';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(W/2-16,H/2);ctx.lineTo(W/2-5,H/2);ctx.moveTo(W/2+5,H/2);ctx.lineTo(W/2+16,H/2);ctx.moveTo(W/2,H/2-16);ctx.lineTo(W/2,H/2-5);ctx.moveTo(W/2,H/2+5);ctx.lineTo(W/2,H/2+16);ctx.stroke();if(flash){ctx.beginPath();ctx.moveTo(W/2-9,H/2-9);ctx.lineTo(W/2+9,H/2+9);ctx.moveTo(W/2+9,H/2-9);ctx.lineTo(W/2-9,H/2+9);ctx.stroke();flash*=.85;if(Math.abs(flash)<.01)flash=0}\n"
" requestAnimationFrame(frame)}\n"
"async function poll(){try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),2000);try{const r=await fetch('/api/state',{signal:controller.signal});if(!r.ok)throw Error('state');app=await r.json()}finally{clearTimeout(timer)}\n"
" $('profile').textContent='Perfil: '+app.title;$('backend').textContent=$('source').value==='keyboard'\?'Demonstração por teclado: ajustes do gyro não alteram estas teclas.':!app.input_ready\?'Sensor indisponível. Você pode usar a demonstração no teclado.':!app.output_ready\?'Sensor conectado; controle virtual indisponível. Confira /dev/uinput.':app.paused\?'Gyro pausado no painel. O analógico físico continua funcionando.':'Sensor e saída virtual disponíveis. O treino usa o controle selecionado no navegador.';\n"
" }catch(e){$('backend').textContent='Aplicativo desconectado. As opções serão liberadas no painel quando a conexão voltar.';app=null}setTimeout(poll,500)}\n"
"window.addEventListener('gamepadconnected',()=>available='');window.addEventListener('gamepaddisconnected',clearInput);requestAnimationFrame(frame);poll();\n"
"</script></body></html>\n";
